sp_widget.client_script:
api.controller = function($scope, spUtil, $rootScope) {
  var c = this;


  c.selectedField = c.data.fields && c.data.fields.length > 0 ? c.data.fields[0].name : '';
  c.searchText = '';
  c.previousSearchText = ''; 
	var searchQuery;


  c.onSearchChange = function() {
    if (c.selectedField) {

      if (c.searchText == '') {
        $rootScope.$broadcast('searchCriteriaChanged', '');
      } 

      else if (c.searchText.length < c.previousSearchText.length) {

         searchQuery = c.selectedField + 'LIKE' + c.previousSearchText;
        $rootScope.$broadcast('searchCriteriaChanged', searchQuery);
      } 

      else {
         searchQuery = c.selectedField + 'LIKE' + c.searchText;
        $rootScope.$broadcast('searchCriteriaChanged', searchQuery);
      }

      // Update the previous search text after broadcasting
      c.previousSearchText = c.searchText;
    }
  };
};

sp_widget.css:
.search-widget {
  margin:10px;
  padding: 10px;
  background-color: #f8f9fa;
  border-radius: 5px;
  box-shadow: 0px 0px 10px rgba(0, 0, 0, 0.1);
  display: flex;
  align-items: center;
}

#fieldDropdown{
width:25rem;
}

.search-widget .form-label {
  font-weight: bold;
  margin-bottom: 0;
}

.search-widget .form-control {
  padding: 8px;
  margin-bottom: 0;
  border: 1px solid #ced4da;
  border-radius: 4px;
}

.search-widget .form-control + .form-control {
  margin-left: 10px;
}

.me-2 {
  margin-right: 10px;
}

sp_widget.script:
(function($sp) {
  data.table = $sp.getValue('table'); // Get the table name
  var fields = $sp.getValue('field_list').split(',');  // Split the field list into an array
  data.fields = [];

  fields.forEach(function(field) {
    var label = '';

    // Query sys_dictionary to get the label for the field
    var grdic = new GlideRecord('sys_dictionary');
    grdic.addQuery('name', data.table); // Filter by table name
    grdic.addQuery('element', field); // Filter by field name
    grdic.query();

    if (grdic.next()) {
      label = grdic.getValue('column_label'); // Fetch the field label
    }

    // Add the field object with name and label
    data.fields.push({
      name: field,
      label: label.toUpperCase() || field.toUpperCase() // Use field name as fallback if label is not found
    });
  });
})($sp);
